"use client";
// src/input.tsx
import {
  input as inputPrimitive,
  inputGroup
} from "@ui-sdk/core/input";
import { controlRender, useFieldControl } from "./field-context.js";
import { controlProps, elementProps } from "./text-control.js";
import {
  createParts,
  usePart,
  usePrimitive
} from "./use-primitive.js";
import { createInputController } from "@ui-sdk/core/input";
function Input({
  value,
  defaultValue,
  onValueChange,
  controller,
  debug,
  render,
  ...props
}) {
  const field = useFieldControl();
  const input = usePrimitive(inputPrimitive, {
    value,
    defaultValue,
    onValueChange,
    controller,
    debug
  });
  const element = {
    ...elementProps(props, field, value, defaultValue),
    render: controlRender(field, "input", render)
  };
  return usePart(input, "root", controlProps(props, field), element, "input");
}
var parts = createParts(inputGroup, { clear: "button" });
function InputGroup({
  debug,
  ...props
}) {
  return usePart(usePrimitive(inputGroup, { debug }), "group", {}, props, "div");
}
var InputClear = parts.Clear;
export {
  Input,
  InputClear,
  InputGroup,
  createInputController
};
